}

var CommitFixture = ""

func (s *ObjectsSuite) TestParseCommit(c *C) {
	data, _ := base64.StdEncoding.DecodeString(CommitFixture)
	commit, err := ParseCommit(data)
	c.Assert(err, IsNil)

	c.Assert(commit.Tree.String(), Equals, "c2d30fa8ef288618f65f6eed6e168e0d514886f4")
	c.Assert(commit.Parents, HasLen, 2)
	c.Assert(commit.Parents[0].String(), Equals, "b029517f6300c2da0f4b651b8642506cd6aaf45d")
	c.Assert(commit.Parents[1].String(), Equals, "b8e471f58bcbca63b07bda20e428190409c2db47")
	c.Assert(commit.Author.Email, Equals, "mcuadros@gmail.com")
	c.Assert(commit.Author.Name, Equals, "Máximo Cuadros")
	c.Assert(commit.Author.When.Unix(), Equals, int64(1427802434))
	c.Assert(commit.Committer.Email, Equals, "mcuadros@gmail.com")
	c.Assert(commit.Message, Equals, "Merge pull request #1 from dripolles/feature\n\nCreating changelog")
}

func (s *ObjectsSuite) TestCommitHash(c *C) {
	data, _ := base64.StdEncoding.DecodeString(CommitFixture)
	commit, err := ParseCommit(data)

	c.Assert(err, IsNil)
	c.Assert(commit.Hash().String(), Equals, "a5b8b09e2f8fcb0bb99d3ccb0958157b40890d69")
}

func (s *ObjectsSuite) TestParseSignature(c *C) {
	cases := map[string]Signature{
		`Foo Bar <foo@bar.com> 1257894000 +0100`: {
			Name:  "Foo Bar",
			Email: "foo@bar.com",
			When:  time.Unix(1257894000, 0),
		},
		`Foo Bar <> 1257894000 +0100`: {
			Name:  "Foo Bar",
			Email: "",
			When:  time.Unix(1257894000, 0),
		},
		` <> 1257894000`: {
			Name:  "",
			Email: "",
			When:  time.Unix(1257894000, 0),
		},
		`Foo Bar <foo@bar.com>`: {
			Name:  "Foo Bar",
			Email: "foo@bar.com",
			When:  time.Time{},
		},
		``: {
			Name:  "",
			Email: "",
			When:  time.Time{},
		},
		`<`: {
			Name:  "",
			Email: "",
			When:  time.Time{},
		},
	}

	for raw, exp := range cases {
		got := ParseSignature([]byte(raw))
		c.Assert(got.Name, Equals, exp.Name)
		c.Assert(got.Email, Equals, exp.Email)
		c.Assert(got.When.Unix(), Equals, exp.When.Unix())
	}
}

package git

import (
	"io"

	"gopkg.in/src-d/go-git.v2/clients"
	"gopkg.in/src-d/go-git.v2/clients/common"
)

type Remote struct {
	Endpoint common.Endpoint

	upSrv  clients.GitUploadPackService
	upInfo *common.GitUploadPackInfo
}

// NewRemote returns a new Remote, using as client http.DefaultClient
func NewRemote(url string) (*Remote, error) {
	end, err := common.NewEndpoint(url)
	if err != nil {
		return nil, err
	}

	return &Remote{
		Endpoint: end,
		upSrv:    clients.NewGitUploadPackService(),
	}, nil
}

// Connect with the endpoint
func (r *Remote) Connect() error {
	if err := r.upSrv.Connect(r.Endpoint); err != nil {
		return err
	}

	var err error
	if r.upInfo, err = r.upSrv.Info(); err != nil {
		return err
	}

	return nil
}

// Capabilities returns the remote capabilities
func (r *Remote) Capabilities() common.Capabilities {
	return r.upInfo.Capabilities
}

// DefaultBranch retrieve the name of the remote's default branch
func (r *Remote) DefaultBranch() string {
	return r.upInfo.Capabilities.SymbolicReference("HEAD")
}

// Fetch returns a reader using the request
func (r *Remote) Fetch(req *common.GitUploadPackRequest) (io.ReadCloser, error) {
	return r.upSrv.Fetch(req)
}

// FetchDefaultBranch returns a reader for the default branch
func (r *Remote) FetchDefaultBranch() (io.ReadCloser, error) {
	return r.Fetch(&common.GitUploadPackRequest{
		Want: []string{r.upInfo.Refs[r.DefaultBranch()].Id},
	})
}

